class ParkingRecord10 {private String reg;private Integer slot;ParkingRecord10(String r,Integer s){setReg(r);setSlot(s);}public String getReg(){return reg;}public Integer getSlot(){return slot;}public void setReg(String r){if(r==null||r.isBlank())throw new IllegalArgumentException("registration required");reg=r;}public void setSlot(Integer s){if(s==null||s<0)throw new IllegalArgumentException("slot must be non-negative");slot=s;}} public class Task10Demo {public static void main(String[]x){ParkingRecord10 p=new ParkingRecord10("TN01AB1234",4);System.out.println(p.getReg()+" slot="+p.getSlot());try{p.setSlot(-1);}catch(IllegalArgumentException e){System.out.println("invalid update rejected");}Integer a=1000,b=1000;System.out.println("Integer equals="+a.equals(b)+"; use equals, not ==, for values.");}}